const route=useRoute(),router=useRouter(),write=mutation()
const desktop=!!(window as unknown as {__TAURI__?:unknown}).__TAURI__
const storage=ref(desktop?'local':'copy'),localIde=ref<InstanceType<typeof LocalProjectIde>|null>(null)
const localConnected=computed(()=>localIde.value?.connected??false)
const usePlan=ref(!!route.query.objective)
const requirementSources=ref<{source_id:string;title:string|null;read_status:string;source_type:string}[]>([]),sourceIds=ref<string[]>([]),incomingSources=ref<string[]>(typeof route.query.source==='string'?[route.query.source]:Array.isArray(route.query.source)?route.query.source.filter((s):s is string=>typeof s==='string'):[])
async function switchStorage(value:string|number|boolean|undefined){if(!await canLeave())return;if(value==='copy')await localIde.value?.disconnect();storage.value=String(value)}
async function bindLocal(id:string){await openWorkspace(id,false);const bound=workspace.value?.study_attempt?.practice_id;const item=workspace.value?.actions.find(a=>a.id===bound);if(item)await resumePractice(item);mode.value='ide'}
async function syncLocal(id:string){if(workspaceId.value===id)workspace.value=await api<Workspace>('/studio/workspaces/'+id)}
async function resolveSources(){if(incomingSources.value.length){return incomingSources.value.slice()}return Promise.all(sourceIds.value.map(async id=>{const row=await api<{snapshots:{source_snapshot_id:string;version_no:number}[]}>('/sources/'+id);const latest=row.snapshots.slice().sort((a,b)=>b.version_no-a.version_no)[0];if(!latest)throw new Error('需求正文不可用');return latest.source_snapshot_id}))}
async function openDelivery(id:string){try{if(localConnected.value){await localIde.value!.prepareSnapshot('submission');await syncLocal(workspaceId.value)}deliveryId.value=id;deliveryOpen.value=true}catch(e){ElMessage.error(String(e))}}
async function retryLocalPatch(id:string){patch.value=workspace.value?.actions.find(a=>a.id===id)??null;if(patch.value)await applyPatch()}

const plans=ref<Plan[]>([]),planId=ref(''),objectiveId=ref(''),units=ref<Unit[]>([]),unitId=ref(''),selections=ref<Selection[]>([])
const knowledgeDialog=ref(false),knowledgeLinks=ref<{link_id:string;citation_id:string;path:string;start_line:number;end_line:number;note:string}[]>([]),knowledgeProjects=ref<{repository_snapshot_id:string;name:string;commit:string;indexed:boolean}[]>([])
const referenceSnapshotId=ref(''),bindStart=ref(1),bindEnd=ref(10)
const mode=ref('reference'),citation=ref<Citation|null>(null),refFiles=ref<RepoFile[]>([]),refPath=ref(''),refText=ref(''),refStart=ref(1),refEnd=ref(1),refTotal=ref(1),highlight=ref<[number,number]>([0,0]),codeBox=ref<HTMLElement|null>(null)
const workspaces=ref<{workspace_id:string;name:string}[]>([]),workspace=ref<Workspace|null>(null),workspaceId=ref(''),filePath=ref(''),editor=ref(''),editorRef=ref<HTMLTextAreaElement|null>(null),gutter=ref<HTMLElement|null>(null)
const agentMode=ref<'learn'|'assist'>('learn'),knowledgeScope=ref<string[]>([]),modelCallLimit=ref(4),codingCallLimit=ref(1)
const agentConfig=ref<{model:string;reasoning_effort:string;max_output_tokens:number}|null>(null)
const practiceId=ref(''),agentPaths=ref<string[]>([]),deliveryId=ref(''),deliveryOpen=ref(false)
const practices=computed(()=>workspace.value?.actions.filter(a=>a.kind==='practice'&&a.status!=='unavailable'&&a.objective_version_id===objectiveId.value)??[])
const selectedPractice=computed(()=>practices.value.find(a=>a.id===practiceId.value))
const independentWorkspace=computed(()=>workspace.value?.study_attempt?.help_mode==='independent')
const runtime=ref<RuntimeCapabilities|null>(null)
const agentActive=computed(()=>!!workspace.value?.active_run||(workspace.value?.actions.some(a=>a.kind==='learning_run'&&['queued','running','waiting_user'].includes(a.status))??false))
const instruction=ref(''),runId=ref(''),busy=ref(false),planDialog=ref(false),patch=ref<Action|null>(null),command=ref('["python", "main.py"]'),fileFilter=ref(''),loadingReference=ref(false)
const selectedPlan=computed(()=>plans.value.find(p=>p.plan_id===planId.value))
const objective=computed(()=>selectedPlan.value?.objectives.find(o=>o.objective_version_id===objectiveId.value))
const relevantUnits=computed(()=>units.value.filter(u=>u.objective_version_id===objectiveId.value))
const unit=computed(()=>relevantUnits.value.find(u=>u.learning_unit_id===unitId.value)??relevantUnits.value[0])
const selection=computed(()=>selections.value.find(s=>s.selection_id===unit.value?.selection_id))
const ownFiles=computed(()=>Object.keys(workspace.value?.files??{}).sort().filter(p=>p.toLowerCase().includes(fileFilter.value.toLowerCase())))
const dirty=computed(()=>localConnected.value?!!localIde.value?.dirty:!!workspace.value&&!!filePath.value&&editor.value!==workspace.value.files[filePath.value])
const codeLines=computed(()=>refText.value.split('\n').map((text,i)=>({number:refStart.value+i,text})))
let navigation=0
async function all<T>(path:string):Promise<T[]>{let cursor:string|null=null;const rows:T[]=[];do{const p:{data:T[];next_cursor?:string|null}=await apiPage<T>(path+(path.includes('?')?'&':'?')+'limit=100'+(cursor?'&cursor='+cursor:''));rows.push(...p.data);cursor=p.next_cursor??null}while(cursor);return rows}
async function load(){try{runtime.value=await api('/studio/runtime-capabilities');requirementSources.value=(await all<{source_id:string;title:string|null;read_status:string;source_type:string}>('/sources')).filter(s=>s.read_status==='available');agentConfig.value=await api('/job-data/agent-config');[plans.value,units.value,selections.value,workspaces.value]=await Promise.all([all<Plan>('/plans'),all<Unit>('/learning-units'),all<Selection>('/project-selections'),api<{workspace_id:string;name:string}[]>('/studio/workspaces')]);if(!planId.value)planId.value=plans.value.find(p=>p.objectives.some(o=>o.objective_version_id===route.query.objective))?.plan_id??plans.value[0]?.plan_id??'';if(!objectiveId.value)objectiveId.value=selectedPlan.value?.objectives.find(o=>o.objective_version_id===route.query.objective)?.objective_version_id??selectedPlan.value?.objectives[0]?.objective_version_id??'';if(!workspace.value&&workspaces.value[0])await openWorkspace(workspaces.value[0].workspace_id);knowledgeProjects.value=await api('/knowledge/projects');await loadKnowledgeLinks();if(route.query.citation)await openCitation(String(route.query.citation));else if(!studyTrackId&&knowledgeLinks.value[0]&&!citation.value)await openCitation(knowledgeLinks.value[0].citation_id);else if(!studyTrackId&&unit.value&&!citation.value)await openStep(unit.value.reading_steps[0]);}catch(e){ElMessage.error(String(e))}}
async function canLeave(){if(!dirty.value&&!localIde.value?.pendingId)return true;try{await ElMessageBox.confirm(localIde.value?.pendingId?'本机补丁已写入，但后端记录尚未同步。离开会结束当前目录会话；可先重试保存应用记录。是否仍离开？':'当前文件有未保存修改，是否放弃这些修改？','切换文件',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'});return true}catch{return false}}
async function loadKnowledgeLinks(){knowledgeLinks.value=objectiveId.value?await api('/knowledge/links?objective_version_id='+objectiveId.value):[]}
async function openKnowledge(id:string){knowledgeDialog.value=false;await openCitation(id)}
async function removeKnowledgeLink(id:string){try{await write('/knowledge/links/'+id,'DELETE',{});await loadKnowledgeLinks()}catch(e){ElMessage.error(String(e))}}
async function chooseObjective(){practiceId.value='';agentPaths.value=[];await loadKnowledgeLinks();unitId.value='';citation.value=null;refText.value='';refFiles.value=[];const link=workspace.value?.links?.find(l=>l.objective_version_id===objectiveId.value);if(link)await openCitation(link.citation_id);else if(knowledgeLinks.value[0])await openCitation(knowledgeLinks.value[0].citation_id);else await openStep(unit.value?.reading_steps[0])}
async function choosePlan(){objectiveId.value=selectedPlan.value?.objectives[0]?.objective_version_id??'';await chooseObjective()}
async function openStep(step:Unit['reading_steps'][number]|undefined){if(!step?.citation_ids.length)return;await openCitation(step.citation_ids[0])}
async function openCitation(id:string){const token=++navigation;loadingReference.value=true;try{const c=await api<Citation>('/citations/'+id);if(token!==navigation)return;citation.value=c;referenceSnapshotId.value=c.repository_snapshot_id;refFiles.value=await all<RepoFile>('/repository-snapshots/'+c.repository_snapshot_id+'/files');if(token!==navigation)return;highlight.value=[c.start_line,c.end_line];sourceTab.value='source';await readReference(c.path,Math.max(1,c.start_line-15));}catch(e){ElMessage.error(String(e))}finally{if(token===navigation)loadingReference.value=false}}
async function readReference(path:string,start=1){if(!referenceSnapshotId.value&&!citation.value&&!selection.value)return;const snapshot=referenceSnapshotId.value||citation.value?.repository_snapshot_id||selection.value!.repository_snapshot_id;const f=refFiles.value.find(f=>f.path===path);refTotal.value=f?.line_count??Math.max(200,citation.value?.end_line??1);refStart.value=Math.max(1,Math.min(start,refTotal.value));refEnd.value=Math.min(refStart.value+199,refTotal.value);const r=await api<{content:string}>('/repository-snapshots/'+snapshot+'/file-content?path='+encodeURIComponent(path)+`&start_line=${refStart.value}&end_line=${refEnd.value}`);refPath.value=path;refText.value=r.content;await nextTick();codeBox.value?.querySelector('.selected-line')?.scrollIntoView({block:'center',behavior:'smooth'})}
async function chooseReference(){try{citation.value=null;highlight.value=[0,0];refFiles.value=await all<RepoFile>('/repository-snapshots/'+referenceSnapshotId.value+'/files');if(refFiles.value[0])await readReference(refFiles.value[0].path)}catch(e){ElMessage.error(String(e))}}
async function bindReference(){if(!workspace.value||!objectiveId.value||!referenceSnapshotId.value||!refPath.value)return;try{workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/reference-links','POST',{objective_version_id:objectiveId.value,repository_snapshot_id:referenceSnapshotId.value,path:refPath.value,start_line:bindStart.value,end_line:bindEnd.value});const link=workspace.value.links?.at(-1);if(link)await openCitation(link.citation_id);ElMessage.success('已绑定到当前学习目标，点击目标即可定位')}catch(e){ElMessage.error(String(e))}}
async function toggleStep(step:Unit['reading_steps'][number]){if(!unit.value)return;try{const ids=new Set(unit.value.progress.completed_step_ids);ids.has(step.step_id)?ids.delete(step.step_id):ids.add(step.step_id);await write('/learning-units/'+unit.value.learning_unit_id+'/progress','PATCH',{expected_version:unit.value.progress.version,completed_step_ids:[...ids],actual_minutes:unit.value.progress.actual_minutes??null,note:unit.value.progress.note??''});units.value=await all<Unit>('/learning-units')}catch(e){ElMessage.error(String(e))}}
async function openWorkspace(id:string,guard=true){if(guard&&!await canLeave())return;try{workspace.value=await api<Workspace>('/studio/workspaces/'+id);workspaceId.value=id;practiceId.value='';agentPaths.value=[];filePath.value=Object.keys(workspace.value.files).sort()[0]??'';editor.value=workspace.value.files[filePath.value]??'';const active=workspace.value.actions.find(a=>a.kind==='learning_run'&&['queued','running','waiting_user'].includes(a.status));runId.value=active?.run_id??''}catch(e){ElMessage.error(String(e))}}
async function openFile(name:string){if(!await canLeave())return;filePath.value=name;editor.value=workspace.value?.files[name]??'';mode.value='ide'}
async function newWorkspace(files:Record<string,string>={}){if(!await canLeave())return;try{const {value}=await ElMessageBox.prompt('为练习项目命名，代码作为独立副本保存。','创建自己的工作区',{inputValue:'我的学习项目'});workspace.value=await write<Workspace>('/studio/workspaces','POST',{name:value,files});workspaceId.value=workspace.value.workspace_id;practiceId.value='';agentPaths.value=[];filePath.value=Object.keys(files)[0]??'';editor.value=files[filePath.value]??'';mode.value='ide';workspaces.value=await api('/studio/workspaces')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(String(e))}}
async function importFolder(event:Event){const input=event.target as HTMLInputElement;const files:Record<string,string>={};let skipped=0;try{for(const file of Array.from(input.files??[])){const name=file.webkitRelativePath.split('/').slice(1).join('/')||file.name;if(name.split('/').some(x=>['.git','.env','.aws','.ssh','.codex','node_modules','.venv','__pycache__'].includes(x)||x.startsWith('.env.'))||file.size>100000||!(/\.(py|js|ts|tsx|jsx|vue|java|json|md|txt|toml|yaml|yml|html|css|sql|xml|properties|sh|gitignore)$/i.test(name))){skipped++;continue}files[name]=await file.text();if(Object.keys(files).length>100)throw new Error('请选择更小的项目目录，最多 100 个文本文件')}if(skipped)ElMessage.info(`已跳过 ${skipped} 个私密、依赖、二进制或过大文件`);if(Object.keys(files).length)await newWorkspace(files)}catch(e){ElMessage.error(String(e))}finally{input.value=''}}
async function newFile(){if(!workspace.value||!await canLeave())return;try{const {value}=await ElMessageBox.prompt('输入相对文件路径，例如 src/main.py','新建文件');if(value in workspace.value!.files)throw new Error('文件已存在');workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/file','PUT',{expected_revision:workspace.value.revision,path:value,content:''});filePath.value=value;editor.value='';mode.value='ide'}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(String(e))}}
async function save(){if(!workspace.value||!filePath.value)return;try{workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/file','PUT',{expected_revision:workspace.value.revision,path:filePath.value,content:editor.value});ElMessage.success('已保存工作区文件')}catch(e){ElMessage.error(String(e))}}
function exportWorkspace(){if(!workspace.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify({name:workspace.value.name,files:workspace.value.files},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=workspace.value.name+'.json';a.click();URL.revokeObjectURL(url)}
async function openLearningPoint(point:LearningPoint){await openCitation(point.citation_id);if(citation.value?.citation_id===point.citation_id){highlight.value=[point.quote_start_line,point.quote_end_line];await readReference(citation.value.path,Math.max(1,point.quote_start_line-12))}}
async function resumePractice(practice:Action){
  if(practice.origin==='study_module'){objectiveId.value=practice.objective_version_id!;practiceId.value=practice.id;agentPaths.value=filePath.value?[filePath.value]:[];agentMode.value='assist';mode.value='ide';return}
  const plan=plans.value.find(p=>p.objectives.some(o=>o.objective_version_id===practice.objective_version_id))
  if(!plan){ElMessage.warning('练习目标不在当前可用计划中，请先恢复或选择对应计划');return}
  usePlan.value=true;planId.value=plan.plan_id;objectiveId.value=practice.objective_version_id!;await chooseObjective()
  practiceId.value=practice.id;agentPaths.value=filePath.value?[filePath.value]:[];practiceView()
  instruction.value='围绕当前迁移练习，先实现一个小步骤。说明引用依据和需要我验证的内容；补丁与命令均由我审阅确认。'
}
async function createPractice(report:Action,index:number){
  if(!workspace.value||busy.value)return
  if(!report.objective_version_id){
    const text=report.guide?.practice[index]??'';if(report.sources?.[0])await openCitation(report.sources[0].citation_id)
    practiceView();instruction.value='基于刚才的学习说明和当前代码依据，实现这个小步骤：'+text;ElMessage.info('练习已带入 Agent 输入；发送后才调用模型');return
  }
  busy.value=true
  try{const r=await write<{workspace:Workspace;practice_id:string}>('/studio/workspaces/'+workspaceId.value+'/learning-reports/'+report.id+'/practices','POST',{expected_revision:workspace.value.revision,exercise_index:index});workspace.value=r.workspace;const practice=workspace.value.actions.find(a=>a.id===r.practice_id);if(practice)await resumePractice(practice);ElMessage.success('练习草稿已保存；点击发送才会调用 Agent')}
  catch(e){ElMessage.error(String(e))}finally{busy.value=false}
}
async function savePracticeNote(id:string,note:string){
  if(!workspace.value||busy.value)return
  busy.value=true
  try{workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/practices/'+id+'/note','PATCH',{expected_revision:workspace.value.revision,note});ElMessage.success('练习笔记已保存')}
  catch(e){ElMessage.error(String(e))}finally{busy.value=false}
}
async function ask(){
  if(!workspace.value||agentActive.value||busy.value)return
  if(independentWorkspace.value){ElMessage.warning('独立工作区禁用 Agent，请本人编辑并提交，或另建辅助尝试');return}
  if(desktop&&storage.value==='local'&&agentMode.value==='assist'&&!localConnected.value){ElMessage.warning('请先打开本机项目，或切换到独立练习副本');return}
  if(agentMode.value==='learn'&&!(usePlan.value&&objectiveId.value)&&!sourceIds.value.length&&!incomingSources.value.length){ElMessage.warning('请选择人工导入的需求资料，或已有学习目标');return}
  if(agentMode.value==='assist'&&workspace.value.study_attempt?.module_key&&studyModule.value&&workspace.value.study_attempt.module_key!==studyModule.value.key){ElMessage.warning('当前项目绑定了另一模块练习，请打开该模块的尝试或创建新尝试');return}
  if(agentMode.value==='assist'&&!instruction.value.trim())return
  if(agentMode.value==='assist'&&dirty.value){ElMessage.warning('请先保存代码，再让 Agent 分析');return}
  busy.value=true
  try{
    const learn=agentMode.value==='learn'
    let localPaths:string[]|null=null
    if(!learn&&localConnected.value){localPaths=(await localIde.value!.prepareSnapshot('agent')).paths;await syncLocal(workspaceId.value)}
    const sources=learn?await resolveSources():[]
    const r=await write<{run_id:string}>('/studio/workspaces/'+workspaceId.value+'/agent-runs','POST',{
      expected_revision:workspace.value.revision,mode:agentMode.value,
      instruction:(!learn&&studyModule.value?JSON.stringify({module:{title:studyModule.value.title,depth:studyModule.value.depth,steps:studyModule.value.steps.slice(0,3),deliverable:studyModule.value.deliverable,acceptance:studyModule.value.acceptance.slice(0,3)},user_request:instruction.value}):instruction.value).trim()||(learn?'根据当前学习目标自主查找相关代码，生成带原文依据的学习说明和小型迁移练习。':''),
      objective_version_id:learn?(sources.length||!usePlan.value?null:objectiveId.value||null):(selectedPractice.value||usePlan.value?objectiveId.value||null:null),source_snapshot_ids:sources,
      practice_id:!learn?selectedPractice.value?.id??null:null,
      citation_ids:!learn&&!selectedPractice.value&&citation.value?[citation.value.citation_id]:[],
      paths:!learn?(localPaths??(selectedPractice.value?agentPaths.value.filter(p=>p in workspace.value!.files):filePath.value?[filePath.value]:[])):[],
      knowledge_snapshot_ids:learn?knowledgeScope.value:[],model_call_limit:modelCallLimit.value,coding_call_limit:codingCallLimit.value
    });runId.value=r.run_id;instruction.value='';await progress()
  }catch(e){ElMessage.error(String(e))}finally{busy.value=false}
}
async function progress(){if(!workspaceId.value)return;try{const wasDirty=dirty.value||localConnected.value;const r=await api<Workspace>('/studio/workspaces/'+workspaceId.value);workspace.value=r;if(r.active_run)runId.value=r.active_run.run_id;if(!wasDirty)editor.value=r.files[filePath.value]??''}catch(e){ElMessage.error(String(e))}}
async function applyPatch(){
  if(!workspace.value||!patch.value)return
  if(independentWorkspace.value&&!patch.value.command_id){ElMessage.warning('独立工作区不能应用 Agent 补丁');return}
  if(desktop&&storage.value==='local'&&!localConnected.value){ElMessage.warning('请先选择对应本机项目，或切换到独立练习副本');return}
  if(dirty.value){ElMessage.warning('请先保存当前文件');return}
  busy.value=true
  try{
    if(localConnected.value){
      const latest=await api<Workspace>('/studio/workspaces/'+workspaceId.value)
      const action=latest.actions.find(a=>a.id===patch.value!.id)
      if(!action||action.status==='unavailable'||!action.edits)throw new Error('补丁依据不可用')
      workspace.value=latest
      if(action.status!=='applied'){
        if(action.edits.some(e=>(latest.files[e.path]??null)!==e.before))throw new Error('后端快照已变化，请重新审阅')
        await localIde.value!.applyPatch(action.id,action.edits)
        workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/patches/'+action.id+'/apply','POST',{expected_revision:latest.revision,confirmation:'APPLY'})
      }
      localIde.value!.recorded();ElMessage.success('补丁已写入本机，应用记录已同步；没有执行命令')
    }else{
      workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/patches/'+patch.value.id+'/apply','POST',{expected_revision:workspace.value.revision,confirmation:'APPLY'});editor.value=workspace.value.files[filePath.value]??'';ElMessage.success('补丁已应用；尚未执行命令')
    }
    patch.value=null
  }catch(e){ElMessage.error(String(e))}finally{busy.value=false}
}
async function propose(){if(!workspace.value)return;try{const argv:unknown=JSON.parse(command.value);if(!Array.isArray(argv)||argv.some(x=>typeof x!=='string'))throw new Error('请输入 JSON 字符串数组');workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/commands','POST',{expected_revision:workspace.value.revision,argv,reason:'用户手动添加命令',practice_id:selectedPractice.value?.id??null})}catch(e){ElMessage.error(String(e))}}
async function execute(a:Action){if(!workspace.value)return;if(desktop&&storage.value==='local'&&!localConnected.value){ElMessage.warning('请先选择项目或切换到独立练习副本');return;}if(dirty.value){ElMessage.warning('请先保存代码');return}try{let scope='';if(localConnected.value){const snapshot=await localIde.value!.prepareSnapshot('command');scope='\n快照文件：'+snapshot.paths.join('、');await syncLocal(workspaceId.value)}runtime.value=await api('/studio/runtime-capabilities');await ElMessageBox.confirm(`${runtimeSummary(runtime.value)}\n工作区：${workspace.value.name}${scope}\n命令：${JSON.stringify(a.argv)}\n在无网络容器执行，最长 30 秒。生成文件仍需审阅应用。`,'确认执行此命令',{confirmButtonText:'确认执行',cancelButtonText:'取消',type:'warning'});busy.value=true;workspace.value=await write<Workspace>('/studio/workspaces/'+workspaceId.value+'/commands/'+a.id+'/execute','POST',{expected_revision:workspace.value.revision,confirmation:'RUN'})}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(String(e));await progress()}finally{busy.value=false}}
function tab(event:KeyboardEvent){if(event.key!=='Tab')return;event.preventDefault();const e=event.target as HTMLTextAreaElement,start=e.selectionStart,end=e.selectionEnd;editor.value=editor.value.slice(0,start)+'  '+editor.value.slice(end);void nextTick(()=>{e.selectionStart=e.selectionEnd=start+2})}

const studyTrackId=typeof route.query.track==='string'?route.query.track:''
const studyData=ref<StudyTrack|null>(null),studyPlanId=ref(typeof route.query.study_plan==='string'?route.query.study_plan:''),studyModuleKey=ref('')
const studyPlan=computed(()=>studyData.value?.plans.find(p=>p.id===studyPlanId.value)??studyData.value?.plans.find(p=>p.id===studyData.value?.active_plan_id)??studyData.value?.plans.at(-1))
const studyModule=computed(()=>studyPlan.value?.modules.find(m=>m.key===studyModuleKey.value))
const studyHighlights=computed(()=>[...(studyData.value?.approved_projects.flatMap(p=>p.highlights)??[]),...(studyPlan.value?.focus_highlights??[])])
let studyLoadNo=0
async function loadStudy(){if(!studyTrackId)return;const n=++studyLoadNo;try{const data=await api<StudyTrack>('/study/tracks/'+studyTrackId);if(n!==studyLoadNo)return;studyData.value=data;if(!studyModuleKey.value)studyModuleKey.value=studyPlan.value?.modules.find(m=>!studyPlan.value?.modules.some(c=>c.parent_key===m.key))?.key??studyPlan.value?.modules[0]?.key??''}catch(e){studyData.value=null;ElMessage.error(String(e))}}
function moduleDepth(key:string){let depth=0,item=studyPlan.value?.modules.find(m=>m.key===key);while(item?.parent_key&&depth<3){depth++;item=studyPlan.value?.modules.find(m=>m.key===item?.parent_key)}return depth}
async function openStudyPoint(point:{citation_id:string;quote_start_line:number;quote_end_line:number}){await openCitation(point.citation_id);if(citation.value?.citation_id===point.citation_id){highlight.value=[point.quote_start_line,point.quote_end_line];await readReference(citation.value.path,Math.max(1,point.quote_start_line-12))}}
async function chooseStudyModule(key:string){studyModuleKey.value=key;const module=studyPlan.value?.modules.find(m=>m.key===key);if(module?.highlight_ids[0])await openCitation(module.highlight_ids[0]);else{citation.value=null;refText.value='';highlight.value=[0,0]}}
async function openModuleAttempt(value:{workspace_id:string;practice_id:string},delivery=false){
 if(!await canLeave())return
 await localIde.value?.disconnect();storage.value='copy';await openWorkspace(value.workspace_id,false)
 const practice=workspace.value?.actions.find(a=>a.id===value.practice_id)
 if(practice)await resumePractice(practice)
 if(delivery)await openDelivery(value.practice_id)
}
async function studyPlanUpdated(value:{kind:string;plan_id:string}){
 if(value.kind==='study'){studyPlanId.value=value.plan_id;await loadStudy()}else await load()
}
async function studyProgress(state:string){if(!studyData.value||!studyPlan.value||!studyModule.value)return;try{studyData.value=await api<StudyTrack>('/study/tracks/'+studyTrackId+'/progress','PUT',{expected_revision:studyData.value.revision,plan_id:studyPlan.value.id,module_key:studyModule.value.key,state});}catch(e){ElMessage.error(String(e))}}
watch(studyModule, module=>{if(module?.highlight_ids[0]&&!citation.value)void openCitation(module.highlight_ids[0])})
watch(mode,value=>{if(studyTrackId&&value==='ide')agentMode.value='assist'})

watch(()=>route.query.study_plan,value=>{if(typeof value==='string'&&value!==studyPlanId.value){studyPlanId.value=value;void loadStudy()}})

function beforeUnload(e:BeforeUnloadEvent){if(dirty.value||localIde.value?.pendingId){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(async()=>{const ok=await canLeave();if(ok)await localIde.value?.disconnect();return ok});onMounted(()=>{void loadStudy();void load();window.addEventListener('beforeunload',beforeUnload)});onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))

// V4.2 presentation state; these controls do not rewrite frozen plans or attempts.
const sideCollapsed=ref(window.innerWidth<760),assistantOpen=ref(false),assistantTab=ref<'study'|'coding'>('study')
const scopeKind=ref<'role'|'goal'>('role'),navigationTracks=ref<{track_id:string;name:string;available:boolean}[]>([])
const viewIntent=ref('learn_project'),sourceTab=ref('source'),lessonStep=ref(0),notesOpen=ref(false),modulePanel=ref(false)
const splitDirection=ref<'horizontal'|'vertical'>('horizontal'),splitPractice=ref(true),focusLine=ref<number|null>(null)
const assistantDrafts={study:'',coding:''}
const intentIcons:Record<string,string>={build_project:'◈',learn_project:'▤',technical_design:'⌘',function:'⌁'}
const shortIntentNames:Record<string,string>={build_project:'项目构建',learn_project:'整个项目',technical_design:'技术设计',function:'函数实现'}
const alternateNames:Record<string,string>={build_project:'构建路线',learn_project:'项目结构',technical_design:'设计重点',function:'实现索引'}
const perspectiveHints:Record<string,string>={build_project:'从模块产物与验收条件开始构建',learn_project:'沿目录与模块关系理解项目',technical_design:'围绕已有步骤与边界阅读设计',function:'从真实引用定位具体函数与实现'}
const moduleReferences=computed(()=>studyModule.value?.highlight_ids.map(id=>studyHighlights.value.find(h=>h.citation_id===id)).filter((h):h is NonNullable<typeof h>=>!!h)??[])
const referenceProjects=computed(()=>{
 const ids=new Set(studyData.value?.approved_projects.filter(p=>studyModule.value?.project_review_ids.includes(p.id)).map(p=>p.repository_snapshot_id).filter(Boolean)??[])
 if(referenceSnapshotId.value)ids.add(referenceSnapshotId.value)
 return knowledgeProjects.value.filter(p=>!studyModule.value||ids.has(p.repository_snapshot_id))
})
const activeReference=computed(()=>knowledgeProjects.value.find(p=>p.repository_snapshot_id===referenceSnapshotId.value))
const leafModules=computed(()=>studyPlan.value?.modules.filter(m=>!studyPlan.value?.modules.some(c=>c.parent_key===m.key))??[])
const panelTitle=computed(()=>studyTrackId?(studyModule.value?.title??studyData.value?.name??'岗位学习计划'):(objective.value?.title??'源码与项目实践'))
const currentStep=computed(()=>studyModule.value?.steps[lessonStep.value]??'选择一个学习目标与代码实现')
const scopeValue=computed(()=>scopeKind.value==='role'?studyTrackId:studyModule.value?.key??objectiveId.value)
async function loadNavigation(){try{navigationTracks.value=await api('/study/tracks')}catch{navigationTracks.value=[]}}
async function switchScope(value:string){
 if(scopeKind.value==='goal'){if(studyData.value)await chooseStudyModule(value);else{objectiveId.value=value;await chooseObjective()}return}
 if(value===studyTrackId||!await canLeave())return
 await router.push({path:'/studio',query:{track:value}})
}
function showAssistant(tab:'study'|'coding'){
 assistantDrafts[assistantTab.value]=instruction.value
 assistantTab.value=tab;instruction.value=assistantDrafts[tab]
 agentMode.value=tab==='coding'?'assist':'learn';assistantOpen.value=true
}
function practiceView(){mode.value='ide';showAssistant('coding')}
function readingView(){mode.value='reference';showAssistant('study')}
async function showStudyStep(key:string,index:number){if(studyModuleKey.value!==key)await chooseStudyModule(key);lessonStep.value=index;notesOpen.value=true}
function selectPerspective(value:string){viewIntent.value=value;sourceTab.value='source'}
async function copyCode(){try{await navigator.clipboard.writeText(refText.value);ElMessage.success('已复制当前源码片段')}catch{ElMessage.warning('当前环境无法复制，请在源码区手动选择复制')}}
function submitPractice(){if(selectedPractice.value)void openDelivery(selectedPractice.value.id);else modulePanel.value=true}
watch(()=>studyPlan.value?.id,()=>{viewIntent.value=studyPlan.value?.intent.kind??'learn_project';lessonStep.value=0},{immediate:true})
watch(studyModuleKey,()=>{lessonStep.value=0;focusLine.value=null})
watch(mode,value=>{if(value==='ide'&&assistantTab.value!=='coding')showAssistant('coding')})
onMounted(loadNavigation)

</script>
<template>
<div class="learning-workspace" :class="{'side-collapsed':sideCollapsed,'assistant-open':assistantOpen,'practice-mode':mode==='ide'}">
<aside class="ws-sidebar" aria-label="学习范围与分级大纲">
<header class="ws-brand"><router-link to="/agent" class="ws-wordmark" title="返回 Agent 工作台"><span class="ws-brand-icon">✦</span><span class="ws-brand-copy"><strong>CareerForge</strong><small>BUILD SKILLS FROM CODE</small></span></router-link><button class="ws-icon-button" :aria-label="sideCollapsed?'展开学习导航':'折叠学习导航'" :aria-expanded="!sideCollapsed" @click="sideCollapsed=!sideCollapsed">{{sideCollapsed?'⇥':'⇤'}}</button></header>
<div class="ws-sidebar-scroll">
<section class="ws-scope"><div class="ws-caption">学习范围</div><div class="ws-segment" role="group" aria-label="学习范围导航"><button :class="{active:scopeKind==='role'}" @click="scopeKind='role'">按岗位</button><button :class="{active:scopeKind==='goal'}" @click="scopeKind='goal'">按目标</button></div><label class="ws-label">{{scopeKind==='role'?'岗位方向':'学习目标'}}</label><el-select :model-value="scopeValue" :placeholder="scopeKind==='role'?'选择已有学习方向':'选择已有学习目标'" @change="switchScope"><template v-if="scopeKind==='role'"><el-option v-for="t in navigationTracks.filter(t=>t.available)" :key="t.track_id" :value="t.track_id" :label="t.name"/></template><template v-else-if="studyPlan"><el-option v-for="m in leafModules" :key="m.key" :value="m.key" :label="m.title"/></template><template v-else><el-option v-for="o in selectedPlan?.objectives" :key="o.objective_version_id" :value="o.objective_version_id" :label="o.title"/></template></el-select><p class="ws-small">{{studyData?.name??'从已有需求与固定版本源码开始学习'}}</p></section>
<section class="ws-perspectives"><div class="ws-caption">学习视角 <span>{{studyPlan?'已有计划':'阅读与实践'}}</span></div><div class="ws-mode-grid"><button v-for="(label,key) in shortIntentNames" :key="key" :class="{active:viewIntent===key}" :title="perspectiveHints[key]" :aria-label="label" @click="selectPerspective(key)"><span>{{intentIcons[key]}}</span><b>{{label}}</b></button></div><p class="ws-small ws-mode-hint">{{perspectiveHints[viewIntent]}}</p></section>
<section v-if="studyTrackId" class="ws-outline-section"><div class="ws-caption">学习大纲 <span>{{studyPlan?.modules.length??0}} 个模块</span></div><el-select v-if="studyData?.plans.length" v-model="studyPlanId" class="ws-plan-select" placeholder="选择已有计划" @change="citation=null;refText='';studyModuleKey='';loadStudy()"><el-option v-for="p in studyData.plans" :key="p.id" :value="p.id" :label="p.title"/></el-select><StudyOutline v-if="studyPlan" :modules="studyPlan.modules" :selected="studyModuleKey" :step="lessonStep" @select="chooseStudyModule" @step="showStudyStep"/><el-empty v-else :image-size="50" description="暂无可用学习计划"/><router-link v-if="!studyPlan" to="/agent" class="ws-inline-link">返回工作台制定计划 →</router-link></section>
<section v-else class="ws-legacy-selection"><div class="ws-caption">需求与源码</div><label class="ws-label">人工导入的需求资料</label><el-select v-model="sourceIds" multiple :multiple-limit="3" clearable placeholder="选择岗位 / 技术资料" @change="incomingSources=[]"><el-option v-for="s in requirementSources" :key="s.source_id" :value="s.source_id" :label="s.title||'未命名资料'"/></el-select><small v-if="incomingSources.length" class="ws-small">已带入 {{incomingSources.length}} 份固定正文</small><label class="ws-label">学习项目范围</label><el-select v-model="knowledgeScope" multiple clearable placeholder="已导入项目"><el-option v-for="p in knowledgeProjects.filter(p=>p.indexed)" :key="p.repository_snapshot_id" :value="p.repository_snapshot_id" :label="p.name"/></el-select><details class="ws-side-details"><summary>已有目标与代码关联</summary><el-checkbox v-model="usePlan">使用已有计划目标</el-checkbox><el-select v-model="planId" placeholder="选择已有计划" @change="choosePlan"><el-option v-for="p in plans" :key="p.plan_id" :value="p.plan_id" :label="`计划 v${p.version} · ${p.kind}`"/></el-select><button v-for="o in selectedPlan?.objectives" :key="o.objective_version_id" class="ws-goal" :class="{active:objectiveId===o.objective_version_id}" @click="objectiveId=o.objective_version_id;chooseObjective()">{{o.title}}</button><el-button link @click="planDialog=true">编辑已有计划</el-button><el-button link @click="knowledgeDialog=true">为当前目标检索代码</el-button><div v-for="l in knowledgeLinks" :key="l.link_id"><el-button link @click="openCitation(l.citation_id)">{{l.path}}:{{l.start_line}}</el-button><el-button link @click="removeKnowledgeLink(l.link_id)">移除</el-button></div><el-button v-for="l in workspace?.links?.filter(l=>l.objective_version_id===objectiveId)" :key="l.citation_id" link @click="openCitation(l.citation_id)">{{l.path}}:{{l.start_line}}</el-button><el-select v-if="relevantUnits.length>1" v-model="unitId" @change="openStep(unit?.reading_steps[0])"><el-option v-for="u in relevantUnits" :key="u.learning_unit_id" :value="u.learning_unit_id" :label="u.why_this_unit"/></el-select><article v-for="s in unit?.reading_steps" :key="s.step_id" class="ws-reading-step"><el-checkbox :model-value="unit?.progress.completed_step_ids.includes(s.step_id)" @change="toggleStep(s)">已阅读</el-checkbox><button @click="openStep(s)">{{s.title}}</button><small>{{s.why}}</small></article></details></section>
</div><footer class="ws-sidebar-footer"><div class="ws-resource-links"><router-link to="/agent" title="Agent 工作台">◈ <span>工作台</span></router-link><router-link to="/sources" title="需求资料">▤ <span>需求</span></router-link><router-link to="/knowledge" title="项目库">⌘ <span>项目</span></router-link></div><small><i/>固定版本 · 进度与能力证据分开记录</small></footer>
</aside>
<main class="ws-center" aria-label="源码学习与个人 IDE">
<header class="ws-taskbar"><div class="ws-task-title"><button class="ws-mobile-nav ws-icon-button" aria-label="展开学习导航" @click="sideCollapsed=!sideCollapsed">☰</button><span class="ws-intent-badge">{{shortIntentNames[viewIntent]}}</span><strong :title="panelTitle">{{panelTitle}}</strong><small v-if="studyModule" :title="currentStep">目标：{{studyModule.depth}} · {{currentStep}}</small></div><div class="ws-task-actions"><el-button size="small" @click="studyTrackId?modulePanel=true:planDialog=true">计划</el-button><el-button v-if="mode==='reference'" size="small" type="primary" @click="practiceView">进入实践 →</el-button><template v-else><el-button size="small" @click="readingView">← 源码学习</el-button><el-button size="small" type="primary" @click="submitPractice">成果与验收</el-button></template><button class="ws-assistant-toggle ws-icon-button" :aria-expanded="assistantOpen" aria-label="切换助手面板" @click="assistantOpen=!assistantOpen">✦</button></div></header>
<div v-if="mode==='ide'" class="ws-practice-strip"><span>{{shortIntentNames[viewIntent]}} · 个人项目</span><b :class="{'is-independent':independentWorkspace}">{{independentWorkspace?'独立尝试':workspace?.study_attempt?'允许 Agent 辅助':'未绑定练习'}}</b><el-button v-if="studyModule" link size="small" @click="modulePanel=true">练习与尝试</el-button><div class="ws-split-controls"><button :class="{active:splitPractice}" @click="splitPractice=!splitPractice">参考分屏</button><button :class="{active:splitDirection==='horizontal'}" @click="splitDirection='horizontal'">▥ 左右</button><button :class="{active:splitDirection==='vertical'}" @click="splitDirection='vertical'">☰ 上下</button></div></div>
<div class="ws-reading-layout" :class="{split:mode==='ide'&&splitPractice,vertical:splitDirection==='vertical'}">
<section v-if="mode==='reference'||splitPractice" class="ws-material reference-panel" aria-label="参考项目源码">
<div class="ws-material-toolbar"><div class="ws-repositories"><strong>参考源码</strong><button v-for="p in referenceProjects.slice(0,3)" :key="p.repository_snapshot_id" :class="{active:referenceSnapshotId===p.repository_snapshot_id}" :title="p.name+' · '+p.commit" @click="referenceSnapshotId=p.repository_snapshot_id;chooseReference()"><span>{{p.name.slice(0,2).toUpperCase()}}</span>{{p.name}}</button><el-select v-if="knowledgeProjects.length>3||!referenceProjects.length" v-model="referenceSnapshotId" size="small" placeholder="选择项目版本" @change="chooseReference"><el-option v-for="p in knowledgeProjects" :key="p.repository_snapshot_id" :value="p.repository_snapshot_id" :label="p.name+' · '+p.commit.slice(0,8)"/></el-select></div><div class="ws-source-tabs"><button :class="{active:sourceTab==='source'}" @click="sourceTab='source'">源码</button><button :class="{active:sourceTab==='details'}" @click="sourceTab='details'">{{alternateNames[viewIntent]}}</button></div></div>
<div class="ws-file-bar"><el-select v-model="refPath" filterable size="small" placeholder="选择参考文件" @change="focusLine=null;readReference(refPath)"><el-option v-for="f in refFiles" :key="f.path" :value="f.path" :label="f.path"/></el-select><span v-if="citation||activeReference" class="ws-commit" :title="citation?.commit??activeReference?.commit">· {{(citation?.commit??activeReference?.commit??'').slice(0,8)}}</span><span class="ws-readonly">只读</span><button class="ws-copy" :disabled="!refText" @click="copyCode">复制</button></div>
<div v-show="sourceTab==='source'" ref="codeBox" v-loading="loadingReference" class="reference-code"><template v-if="refText"><div v-for="line in codeLines" :key="line.number" class="code-line" :class="{'selected-line':refPath===citation?.path&&line.number>=highlight[0]&&line.number<=highlight[1],'focused-line':focusLine===line.number}"><button class="line-number" :aria-label="'定位第 '+line.number+' 行'" @click="focusLine=line.number">{{line.number}}</button><CodeSyntax :text="line.text||' '"/></div></template><div v-else class="ws-code-empty"><span>⌘</span><strong>从一个真实实现开始</strong><p>选择左侧学习模块、参考项目或已有代码引用。</p><el-button size="small" @click="knowledgeDialog=true">检索已导入源码</el-button></div></div>
<div v-if="sourceTab==='details'" class="ws-alternate"><span class="ws-overline">{{shortIntentNames[viewIntent]}} / {{alternateNames[viewIntent]}}</span><h2>{{panelTitle}}</h2><p class="ws-small">{{studyPlan?.summary??(!studyTrackId?objective?.target_behavior:undefined)??'请选择已有学习目标和固定源码，查看其真实资料。'}}</p><template v-if="viewIntent==='learn_project'"><h3>固定版本目录</h3><button v-for="f in refFiles" :key="f.path" class="ws-file-entry" @click="sourceTab='source';readReference(f.path)"><span>▤ {{f.path}}</span><small>{{f.line_count}} 行</small></button><p v-if="!refFiles.length" class="ws-small">尚未选择源码版本。</p></template><template v-else-if="viewIntent==='function'"><h3>当前模块的实现索引</h3><button v-for="h in moduleReferences" :key="h.citation_id" class="ws-reference-index" @click="sourceTab='source';openCitation(h.citation_id)"><strong>{{h.path}}:{{h.start_line}}–{{h.end_line}}</strong><p>{{h.explanation}}</p><pre>{{h.quote}}</pre></button><p v-if="!moduleReferences.length" class="ws-small">没有新增函数对应关系；请从已有代码引用或检索结果定位。</p></template><template v-else><h3>{{viewIntent==='build_project'?'已有模块的构建步骤':'已有计划中的设计学习重点'}}</h3><ol><li v-for="step in studyModule?.steps" :key="step">{{step}}</li></ol><div v-if="studyModule" class="ws-goal-card"><span>预期产物</span><p>{{studyModule.deliverable}}</p><strong>可观察验收条件</strong><ul><li v-for="item in studyModule.acceptance" :key="item">{{item}}</li></ul></div></template><p class="ws-small">此处仅调整阅读视角。计划与已冻结练习保持原版本；源码位置有效不代表语义或运行效果已核验。</p></div>
<footer class="ws-code-footer"><span :title="citation?.commit??''">{{activeReference?.name??'参考源码'}} · {{citation&&refPath===citation.path?'引用 '+highlight[0]+'–'+highlight[1]+' 行':'固定版本阅读'}}</span><div><button :disabled="!refText||refStart<=1" @click="readReference(refPath,Math.max(1,refStart-200))">‹</button><small>{{refText?refStart+'–'+refEnd+' / '+refTotal:'待定位'}}</small><button :disabled="!refText||refEnd>=refTotal" @click="readReference(refPath,refEnd+1)">›</button></div></footer>
</section>
<section v-show="mode==='ide'" class="ws-material own-project" aria-label="个人项目 IDE"><div class="ws-material-toolbar"><strong>我的构建 IDE</strong><span class="ws-file-chip">{{filePath||workspace?.name||'尚未打开项目'}}</span><el-radio-group v-if="desktop" :model-value="storage" size="small" @change="switchStorage"><el-radio-button value="local">本机</el-radio-button><el-radio-button value="copy">副本</el-radio-button></el-radio-group></div><div v-show="storage==='copy'" class="ws-copy-ide"><div class="ws-workspace-toolbar"><el-select :model-value="workspaceId" size="small" placeholder="选择项目副本" @change="openWorkspace"><el-option v-for="w in workspaces" :key="w.workspace_id" :value="w.workspace_id" :label="w.name"/></el-select><el-button size="small" @click="newWorkspace()">＋ 新建</el-button><label class="ws-import" title="导入为独立副本">导入目录<input type="file" webkitdirectory multiple @change="importFolder"/></label></div><div v-if="workspace" class="ide"><aside class="file-tree"><el-input v-model="fileFilter" size="small" placeholder="查找文件"/><el-button link size="small" @click="newFile">＋ 文件</el-button><button v-for="name in ownFiles" :key="name" :class="{active:name===filePath}" :title="name" @click="openFile(name)">{{name}}</button></aside><div class="editor-panel"><div class="ws-editor-toolbar"><span>{{filePath||'选择文件'}}{{dirty?' ●':''}}</span><el-button size="small" :disabled="!filePath||!dirty" @click="save">保存</el-button></div><div class="text-editor"><pre ref="gutter" class="line-gutter">{{editor.split('\n').map((_,i)=>i+1).join('\n')}}</pre><textarea ref="editorRef" v-model="editor" :disabled="!filePath" spellcheck="false" aria-label="项目代码编辑器" @keydown="tab" @keydown.ctrl.s.prevent="save" @keydown.meta.s.prevent="save" @scroll="gutter&&(gutter.scrollTop=editorRef?.scrollTop??0)"/></div></div></div><div v-else class="ws-project-empty"><strong>开始自己的项目</strong><p>新建独立工作区，或导入一个目录副本。</p><el-button type="primary" size="small" @click="newWorkspace()">新建工作区</el-button></div></div>
