<details v-if="workspace" class="ws-command-details"><summary>运行与快照 · 每条命令需确认</summary><el-input v-model="command" size="small" placeholder='["python", "main.py"]'/><el-button size="small" @click="propose">添加待确认命令</el-button><p>{{runtimeSummary(runtime)}}</p><el-button link @click="exportWorkspace">导出工作区 JSON</el-button></details><footer class="ws-code-footer"><span>{{localConnected?'直接编辑已授权的本机目录':'独立项目副本 · Ctrl/⌘ S 保存'}}</span><button @click="showAssistant('coding')">请求 Review ↗</button></footer></section>
