<aside class="ws-assistant" aria-label="学习与 Coding 助手"><header class="ws-assistant-header"><div class="ws-assistant-brand"><span :class="{coding:assistantTab==='coding'}">{{assistantTab==='coding'?'⌘':'✦'}}</span><div><strong>{{assistantTab==='coding'?'Pi Coding Agent':'CareerForge 学习助手'}}</strong><small>{{assistantTab==='coding'?'代码编辑与补丁审阅':'解读学习计划 · 解释项目源码'}}</small></div><i/><button class="ws-assistant-close ws-icon-button" aria-label="收起助手" @click="assistantOpen=false">×</button></div><div class="ws-segment" role="tablist" aria-label="对话上下文"><button role="tab" :aria-selected="assistantTab==='study'" :class="{active:assistantTab==='study'}" @click="showAssistant('study')">◈ 学习助手</button><button role="tab" :aria-selected="assistantTab==='coding'" :class="{active:assistantTab==='coding'}" @click="showAssistant('coding')">⌘ Pi Coding</button></div><p>{{assistantTab==='coding'?'Pi SDK 使用明确选择的文件与引用；补丁审阅后应用，命令逐条确认。':'学习问答与 Coding 请求分别展示；切换目录和视角不会自动发送消息。'}}</p></header>
