<div v-if="studyTrackId&&(!studyData||!studyPlan||!studyModule)" v-show="assistantTab==='study'" class="ws-agent-body"><div class="ws-chat-empty"><span>✦</span><strong>先选择已有学习计划</strong><p>当前岗位方向尚无可用计划模块。请到工作台选择或制定计划，再围绕具体模块提问。</p><router-link to="/agent" class="ws-inline-link">打开 Agent 工作台 →</router-link></div></div>
<div v-show="assistantTab==='coding'||!studyTrackId" class="ws-agent-body"><div class="ws-conversation"><div v-if="!workspace" class="ws-chat-empty"><span>✦</span><strong>{{assistantTab==='study'?'从一个问题开始学习':'开始构建你的项目'}}</strong><p>选择或创建自己的工作区后，发送请求才调用 Agent。</p><el-button size="small" @click="newWorkspace()">{{assistantTab==='study'?'创建学习会话':'创建项目工作区'}}</el-button></div><template v-for="a in workspace?.actions" :key="a.id"><article v-if="(assistantTab==='study'&&(a.kind==='learning_report'||a.kind==='learning_run'))||(assistantTab==='coding'&&!['learning_report','learning_run'].includes(a.kind))" class="ws-action"><LearningExplanation v-if="a.kind==='learning_report'||a.kind==='learning_run'" :report="a" @open="openCitation" @point="openLearningPoint" @run="id=>runId=id" @practice="index=>createPractice(a,index)"/><PracticeCard v-else-if="a.kind==='practice'" :practice="a" :actions="workspace?.actions??[]" :selected="selectedPractice?.id===a.id" :busy="busy" @resume="resumePractice(a)" @save="note=>savePracticeNote(a.id,note)" @open="openCitation" @delivery="openDelivery(a.id)"/><el-alert v-else-if="a.status==='unavailable'" title="依据已不可用，输出已隐藏" type="warning" :closable="false"/><template v-else-if="a.kind==='message'"><p class="ws-user-message">{{a.instruction}}</p><div class="ws-answer">{{a.answer}}</div><el-button v-for="id in a.citation_ids" :key="id" link @click="openCitation(id)">查看代码依据</el-button><small v-if="a.usage" class="ws-small">token {{a.usage.input_tokens}} / {{a.usage.output_tokens}}</small></template><template v-else-if="a.kind==='patch'"><strong>代码变更 · {{a.status==='applied'?'已应用':'待审阅'}}</strong><p>{{a.edits?.map(e=>e.path).join('、')}}</p><el-button size="small" :disabled="a.status==='applied'||independentWorkspace" @click="patch=a">审阅补丁</el-button></template><template v-else-if="a.kind==='command'"><strong>命令 · {{a.status}}</strong><pre>{{JSON.stringify(a.argv)}}</pre><p>{{a.reason}}</p><el-button v-if="a.status==='pending'" size="small" :loading="busy" @click="execute(a)">确认后执行</el-button><p v-if="a.exit_code!==undefined">退出码 {{a.exit_code}}（仅本命令结果）</p><pre v-if="a.stdout||a.stderr">{{a.stdout}}{{a.stderr}}</pre><el-alert v-if="a.error" :title="a.error" type="warning" :closable="false"/></template></article></template><div v-if="workspace&&!workspace.actions.length" class="ws-chat-empty"><span>✦</span><strong>随时询问当前实现</strong><p>代码解释、变更和命令建议均在这里呈现。只有你显式发送才会调用模型。</p></div><details v-if="runId" class="ws-run-progress"><summary>查看任务进度</summary><RunPanel :key="runId" :run-id="runId" @changed="progress"/></details></div>
<div class="ws-composer-footer"><div class="ws-context-banner" :class="{coding:assistantTab==='coding'}"><strong>{{assistantTab==='coding'?'CODING · '+(independentWorkspace?'独立模式（助手停用）':'当前项目'):'当前学习上下文'}}</strong><span>{{assistantTab==='coding'?workspace?.name??'尚未选择项目':panelTitle}}</span></div><details class="ws-assistant-settings"><summary>上下文与模型预算</summary><p>{{agentConfig?.model??'未读取配置'}} · {{agentConfig?.reasoning_effort??'low'}} · 每次最多 {{agentConfig?.max_output_tokens??'—'}} 输出 token</p><template v-if="assistantTab==='study'"><el-select v-model="modelCallLimit" size="small"><el-option v-for="n in [2,3,4]" :key="n" :value="n" :label="n+' 次模型调用'"/></el-select></template><template v-else><el-select v-model="codingCallLimit" size="small"><el-option v-for="n in [1,2,3,4]" :key="n" :value="n" :label="n+' 次 Coding 模型调用'"/></el-select><el-select v-model="practiceId" clearable size="small" placeholder="选择已有练习"><el-option v-for="p in practices" :key="p.id" :value="p.id" :label="p.exercise?.slice(0,60)"/></el-select><el-select v-if="selectedPractice" v-model="agentPaths" multiple :multiple-limit="3" size="small" placeholder="明确发送的已保存文件"><el-option v-for="name in Object.keys(workspace?.files??{}).sort()" :key="name" :value="name" :label="name"/></el-select></template></details><div class="ws-suggestions"><button @click="instruction=assistantTab==='coding'?'请审阅当前已保存的代码，指出具体问题和验证建议。':'解释当前代码的关键流程和边界。'">{{assistantTab==='coding'?'请求 Review':'解释当前代码'}}</button><button @click="instruction=assistantTab==='coding'?'根据当前目标提出一组可供我审阅的最小代码变更。':'围绕当前目标建议下一步学习顺序。'">{{assistantTab==='coding'?'生成补丁':'下一步怎么学？'}}</button></div><div class="ws-composer"><el-input v-model="instruction" type="textarea" :rows="2" :placeholder="assistantTab==='coding'?'向 Coding Agent 描述修改或审阅要求…':'询问当前目标或希望理解的代码…'" @keydown.enter.exact.prevent="ask"/><button class="ws-send-button" :disabled="independentWorkspace||!workspace||agentActive||busy||(agentMode==='learn'?(!(usePlan&&objectiveId)&&!sourceIds.length&&!incomingSources.length):!instruction.trim())" :aria-label="assistantTab==='coding'?'发送 Coding 请求':'发送学习请求'" @click="ask">{{busy?'…':'➤'}}</button></div><small class="ws-chat-meta">{{assistantTab==='coding'?'Coding':'学习'}}会话 · 显式发送才调用模型 <span>Enter 发送</span></small></div></div>
</aside>
